import { MakeLogicType, afterMount, connect, kea, key, listeners, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import { loadAppMetricsTotals } from 'lib/components/AppMetrics/appMetricsLogic'
import { billingLogic } from 'scenes/billing/billingLogic'

import type { BillingPeriod } from '~/types'

import { DATA_WAREHOUSE_APP_SOURCE } from 'products/data_warehouse/frontend/shared/components/metrics/DataWarehouseMetrics'

export interface SourceBillingUsageLogicProps {
    sourceId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sourceBillingUsageLogicValues {
    billingPeriodUTC: BillingPeriod // billingLogic
    rowsSyncedThisPeriod: number | null
    rowsSyncedThisPeriodLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sourceBillingUsageLogicActions {
    loadBillingSuccess: (
        billing: import('~/types').BillingType,
        payload?: any
    ) => {
        billing: import('~/types').BillingType
        payload?: any
    } // billingLogic
    loadRowsSyncedThisPeriod: () => any
    loadRowsSyncedThisPeriodFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadRowsSyncedThisPeriodSuccess: (
        rowsSyncedThisPeriod: number | null,
        payload?: any
    ) => {
        rowsSyncedThisPeriod: number | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sourceBillingUsageLogicMeta {
    key: string
}

export type sourceBillingUsageLogicType = MakeLogicType<
    sourceBillingUsageLogicValues,
    sourceBillingUsageLogicActions,
    SourceBillingUsageLogicProps,
    sourceBillingUsageLogicMeta
>

// Rows synced (not rows stored) is the quantity data warehouse usage is metered on: every row
// imported on every run counts, so a full-refresh table re-imports its rows on each sync. We read
// the same `rows_synced` app metric the source metrics view already shows, summed over the org's
// current billing period, so the figure lines up with what drives billing rather than the row count
// currently sitting in the destination table.
export const sourceBillingUsageLogic = kea<sourceBillingUsageLogicType>([
    path(['products', 'data_warehouse', 'frontend', 'scenes', 'SourceScene', 'tabs', 'sourceBillingUsageLogic']),
    props({} as SourceBillingUsageLogicProps),
    key((props) => props.sourceId),
    connect(() => ({
        values: [billingLogic, ['billingPeriodUTC']],
        actions: [billingLogic, ['loadBillingSuccess']],
    })),
    loaders(({ props, values }) => ({
        rowsSyncedThisPeriod: [
            null as number | null,
            {
                loadRowsSyncedThisPeriod: async () => {
                    const { start, end } = values.billingPeriodUTC
                    if (!start || !end) {
                        return null
                    }
                    // Absolute period bounds — query in UTC so the window matches the billing period
                    // regardless of the project timezone.
                    const totals = await loadAppMetricsTotals(
                        {
                            appSource: DATA_WAREHOUSE_APP_SOURCE,
                            appSourceId: props.sourceId,
                            metricName: 'rows_synced',
                            breakdownBy: ['metric_name'],
                            dateFrom: start.format('YYYY-MM-DD HH:mm:ss'),
                            dateTo: end.format('YYYY-MM-DD HH:mm:ss'),
                        },
                        'UTC'
                    )
                    return Object.values(totals).reduce((sum, row) => sum + row.total, 0)
                },
            },
        ],
    })),
    listeners(({ actions, values }) => ({
        // Billing loads app-wide and asynchronously; refresh once the period is known if it wasn't
        // already available at mount.
        loadBillingSuccess: () => {
            if (values.billingPeriodUTC.start && values.billingPeriodUTC.end) {
                actions.loadRowsSyncedThisPeriod()
            }
        },
    })),
    afterMount(({ actions, values }) => {
        if (values.billingPeriodUTC.start && values.billingPeriodUTC.end) {
            actions.loadRowsSyncedThisPeriod()
        }
    }),
])
